// Map known order names to their SVG keys
const ORDER_MAP: Record<string, string> = {
  lepidoptera: 'lepidoptera',
  coleoptera: 'coleoptera',
  hymenoptera: 'hymenoptera',
  odonata: 'odonata',
  diptera: 'diptera',
  hemiptera: 'hemiptera',
  araneae: 'araneae',
};

export function getTaxonVisuals(iconicName?: string, taxon?: InatTaxon): TaxonVisual {
  const normIconic = (iconicName || taxon?.iconic_taxon_name || '').toLowerCase();

  // Check if taxon rank is order or has order ancestors
  let orderKey: string | undefined;
  if (taxon) {
    const taxonNameLower = (taxon.name || '').toLowerCase();
    if (ORDER_MAP[taxonNameLower]) {
      orderKey = ORDER_MAP[taxonNameLower];
    }
  }

  // Determine iconic taxon color and SVG element
  switch (normIconic) {
    case 'plantae':
      return {
        key: 'plantae',
        label: 'Rostliny',
        color: INAT_COLORS.green,
        svgInner: SVG_ELEMENTS.plantae || SVG_ELEMENTS.unknown,
      };

    case 'insecta':
      return {
        key: orderKey || 'insecta',
        label: orderKey ? orderKey.charAt(0).toUpperCase() + orderKey.slice(1) : 'Hmyz',
        color: INAT_COLORS.orange,
        svgInner: (orderKey && SVG_ELEMENTS[orderKey]) ? SVG_ELEMENTS[orderKey] : SVG_ELEMENTS.insecta,
      };

    case 'arachnida':
      return {
        key: orderKey || 'arachnida',
        label: 'Pavoukovci',
        color: INAT_COLORS.orange,
        svgInner: (orderKey && SVG_ELEMENTS[orderKey]) ? SVG_ELEMENTS[orderKey] : SVG_ELEMENTS.arachnida,
      };

    case 'mollusca':
      return {
        key: 'mollusca',
        label: 'Měkkýši',
        color: INAT_COLORS.orange,
        svgInner: SVG_ELEMENTS.mollusca || SVG_ELEMENTS.unknown,
      };

    case 'aves':
      return {
        key: 'aves',
        label: 'Ptáci',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.aves || SVG_ELEMENTS.unknown,
      };

    case 'mammalia':
      return {
        key: 'mammalia',
        label: 'Savci',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.mammalia || SVG_ELEMENTS.unknown,
      };

    case 'reptilia':
      return {
        key: 'reptilia',
        label: 'Plazi',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.reptilia || SVG_ELEMENTS.unknown,
      };

    case 'amphibia':
      return {
        key: 'amphibia',
        label: 'Obojživelníci',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.amphibia || SVG_ELEMENTS.unknown,
      };

    case 'actinopterygii':
      return {
        key: 'actinopterygii',
        label: 'Paprskoploutví',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.actinopterygii || SVG_ELEMENTS.unknown,
      };

    case 'animalia':
      return {
        key: 'animalia',
        label: 'Ostatní živočichové',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.animalia || SVG_ELEMENTS.unknown,
      };

    case 'fungi':
      return {
        key: 'fungi',
        label: 'Houby',
        color: INAT_COLORS.pink,
        svgInner: SVG_ELEMENTS.fungi || SVG_ELEMENTS.unknown,
      };

    case 'chromista':
      return {
        key: 'chromista',
        label: 'Chromista',
        color: INAT_COLORS.brown,
        svgInner: SVG_ELEMENTS.chromista || SVG_ELEMENTS.unknown,
      };

    case 'protozoa':
      return {
        key: 'protozoa',
        label: 'Prvoci',
        color: INAT_COLORS.purple,
        svgInner: SVG_ELEMENTS.protozoa || SVG_ELEMENTS.unknown,
      };

    default:
      return {
        key: 'unknown',
        label: 'Neznámý taxon',
        color: INAT_COLORS.gray,
        svgInner: SVG_ELEMENTS.unknown,
      };
  }
}
